        .main-title {
            position: absolute;
            top: 60px;
            left: 50px;
        }
        .main-title-line1 {
            font-size: 110px;
            font-weight: bold;
            letter-spacing: 20px;
            line-height: 1;
        }
        .main-title-line2 {
            font-size: 110px;
            font-weight: bold;
            letter-spacing: 20px;
            line-height: 1;
            margin-top: 15px;
        }

        .english-title {
            position: absolute;
            top: 75px;
            left: 320px;
            font-size: 24px;
            font-weight: bold;
            line-height: 1.2;
            letter-spacing: 1px;
        }

        .red-seal {
            position: absolute;
            top: 80px;
            left: 490px;
            display: grid;
            grid-template-columns: 1fr 1fr;
            width: 55px;
            height: 55px;
            background-color: #d81e06;
            color: #fff;
            font-size: 18px;
            font-family: "KaiTi", serif;
            align-items: center;
            justify-items: center;
            padding: 4px;
            box-sizing: border-box;
        }

        /* Top Right Vertical Text */
        .top-right-text {
            position: absolute;
            top: 70px;
            right: 60px;
            display: flex;
            font-size: 22px;
            font-weight: bold;
            letter-spacing: 6px;
        }
        .top-right-col {
            width: 30px;
            text-align: center;
            line-height: 1.2;
        }
        .line-left {
            border-left: 2px solid #103b31;
            padding-left: 15px;
        }
        .no-line {
            margin-left: 15px;
        }

        /* Left Sidebar (Date & Vertical Text) */
        .left-sidebar {
            position: absolute;
            top: 360px;
            left: 50px;
            z-index: 10;
        }
        .vertical-timeline {
            position: absolute;
            left: 0;
            top: 15px;
            bottom: -15px;
            width: 2px;
            background-color: #103b31;
        }
        .vertical-timeline::before, .vertical-timeline::after {
            content: '';
            position: absolute;
            left: -4px;
            width: 10px;
            height: 10px;
            border-radius: 50%;
            background-color: #103b31;
        }
        .vertical-timeline::before { top: 0; }
        .vertical-timeline::after { bottom: 0; }

        .left-content {
            padding-left: 30px;
        }
        .date-label {
            font-size: 28px;
            font-weight: bold;
            letter-spacing: 2px;
        }
        .date-year {
            font-size: 36px;
            font-weight: bold;
            margin-top: 5px;
        }
        .date-fraction {
            position: relative;
            height: 110px;
            margin-top: 15px;
        }
        .date-month {
            position: absolute;
            top: 0;
            left: 0;
            font-size: 75px;
            line-height: 1;
        }
        .date-slash {
            position: absolute;
            top: 30px;
            left: 35px;
            font-size: 55px;
            font-weight: 200;
        }
        .date-day {
            position: absolute;
            top: 65px;
            left: 65px;
            font-size: 48px;
            line-height: 1;
            font-weight: bold;
        }

        .left-vertical-words {
            display: flex;
            margin-top: 70px;
            font-size: 22px;
            font-weight: bold;
        }
        .left-vertical-words > div {
            line-height: 2.5;
        }
        .word-col-1 {
            margin-right: 30px;
        }

        .small-image-placeholder {
            width: 100px;
            height: 130px;
            border: 2px solid #103b31;
            margin-top: 70px;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            text-align: center;
            background-color: rgba(16, 59, 49, 0.1);
        }

        /* Right Paragraph */
        .right-paragraph {
            position: absolute;
            top: 280px;
            right: 60px;
            writing-mode: vertical-rl;
            height: 520px;
            font-size: 15px;
            line-height: 2.2;
            letter-spacing: 3px;
            text-align: justify;
            z-index: 10;
