        .main-image-placeholder {
            position: absolute;
            top: 310px;
            left: 50%;
            transform: translateX(-50%);
            width: 580px;
            height: 820px;
            border: 2px dashed #103b31;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 28px;
            font-weight: bold;
            background-color: rgba(16, 59, 49, 0.05);
            z-index: 1;
        }
    </style>
</head>
